      "资金需求特点与周期": "资本补充需求（偿付能力约束，3-5年周期通过资本债/次级债补充）、投资资金（长期资金匹配长期负债，配置非标和权益资产）、IT建设（3年迭代周期）",
      "前景趋势判断": "保险行业正经历从规模扩张向价值经营转型，保障型产品占比提升，分红险和万能险结算利率下行应对利差损压力，银保渠道深度调整（报行合一），车险综合改革后费用率压缩，康养产业链延伸成为新增长点",
      "毛利率区间": "寿险新业务价值率20%-45%（保障型高，储蓄型低），财险综合成本率97%-100%（车险偏低，非车偏高）",
      "净利率区间": "寿险5%-15%（准备金和获取成本侵蚀），财险2%-8%（综合成本率影响大）",
      "旺季月份": "12月-1月（开门红和年报冲刺）、6月（半年考核冲量）、9-10月（秋季产品集中推广）",
      "淡季月份": "2-3月（春节假期和开门红后回落）、7-8月（夏季淡季）",
      "季节性资金缺口高峰": "①12月-1月：开门红集中销售导致佣金和手续费集中支付；②6月末：半年考核赔付和费用集中；③9月末：三季度赔付和准备金计提",
      "主要经营风险": "①利差损风险（投资收益率低于产品定价利率）；②退保率上升（经济压力导致退保）；③赔付率上升（自然灾害和疫情等巨灾风险）；④偿付能力充足率达标压力；⑤投资亏损风险",
      "政策与外部驱动": "偿二代二期工程、车险综合改革、银保渠道报行合一、互联网保险监管、商业养老保险税收递延政策、巨灾保险制度建设",
      "必备证照资质": "保险许可证（金融监管总局核发）、营业执照、偿付能力达标",
