      "成本结构（占比）": "派遣按人头收管理费（每人每月50-300元），毛利低但量大；外包按项目结算毛利10%-20%",
      "资金需求特点与周期": "上游：用工单位月结或双月结（账期30-90天，含代收代付工资）。下游：员工工资月度刚性发放、社保公积金按月申报缴纳",
