      "前景趋势判断": "家装随二手房交易与存量房翻新支撑，新房装修下行；工装受商业地产、连锁品牌扩张、酒店改造影响。存量翻新与适老化改造是增量",
      "毛利率区间": "工装15%-30%，家装25%-40%（含设计费）",
      "净利率区间": "5%-12%（家装获客成本高，净利被营销侵蚀）",
      "旺季月份": "3-5月、9-11月（装修旺季）；交房季（各地不同）后2-3个月是家装高峰",
