      "季节性资金缺口高峰": "①旺季开工前的材料与人工备付；②工装项目垫资施工期；③年底集中交付前的赶工成本",
      "主要经营风险": "①家装客户预收款挪用与跑路（行业负面声誉）；②工装垫资与账期；③材料环保标准提升导致成本上升；④工人短缺与人工涨价；⑤设计与施工脱节导致返工",
      "政策与外部驱动": "以旧换新与家装消费补贴、存量房交易活跃度、连锁品牌扩张节奏、绿色建材与环保标准",
      "必备证照资质": "建筑装修装饰工程专业承包资质、安全生产许可证；家装个体户仅需营业执照",
      "订单与客户来源": "工装：总包分包、企业办公场所、酒店商场、连锁品牌门店；家装：楼盘交房、小区驻点、线上平台、熟人推荐",
      "典型融资用途": "材料采购垫资、工人工资、样板间与门店租金"
